/* Dashboard, Tasks, Email, Calendar, Quotations. */
(function () {
  const { esc, dash, fmtDate, fmtDT, rel, badge, prio, userLabel, opts, I, modal, toast, form, tile } = UI;
  const db = () => Store.db;
  const taskRow = (t) => '<label class="task' + (Store.isOverdue(t) ? ' over' : '') + (t.done ? ' done' : '') + '"><input type="checkbox" data-task="' + t.id + '"' + (t.done ? ' checked' : '') + '><span class="grow"><strong>' + esc(t.title) + '</strong><span class="m">' + (Store.isOverdue(t) ? 'Overdue · ' : Store.isToday(t) ? 'Today · ' : fmtDate(t.due) + ' · ') + (t.leadId ? '<a href="#/leads/' + t.leadId + '">' + t.leadId + '</a> · ' : '') + esc(t.origin) + ' · ' + esc(Store.userName(t.assignedTo)) + '</span></span>' + (Store.isOverdue(t) ? badge('Overdue', 'b-bad') : Store.isToday(t) ? badge('Today', 'b-purple') : badge('Upcoming', 'b-grey')) + '</label>';
  const bindTasks = (el) => el.querySelectorAll('[data-task]').forEach((cb) => cb.addEventListener('change', () => { Store.toggleTask(cb.dataset.task); }));

  /* ---------- Dashboard ---------- */
  V.dashboard = function () {
    const me = Store.currentUser(); const t = Store.today();
    const my = db().tasks.filter((x) => x.assignedTo === me.id && !x.done).sort((a, b) => (a.due > b.due ? 1 : -1));
    const myLeads = db().leads.filter((l) => l.assignedTo === me.id && !l.archived && !['Won', 'Lost', 'Not Relevant'].includes(l.status));
    const todayEv = db().events.filter((e) => e.date === t).sort((a, b) => (a.start > b.start ? 1 : -1));
    const notes = db().notifications.filter((n) => n.userId === me.id).slice(0, 5);
    const myQuotes = db().quotes.filter((x) => x.ownerId === me.id && ['Sent', 'Negotiating'].includes(x.status));
    const byStatus = db().config.leadStatuses.slice(0, 7).map((s) => [s, myLeads.filter((l) => l.status === s).length]); const max = Math.max(1, ...byStatus.map((x) => x[1]));
    const html = topbar('Good afternoon, ' + esc(me.name.split(' ')[0]), 'Wednesday 18 November 2026 · everything assigned to you across leads, email, calendar and quotations', '<button class="btn" data-act="notes" style="position:relative" aria-label="Notifications">🔔' + (Store.counts.notifications(me.id) ? '<span class="badge b-warn" style="position:absolute;top:-6px;right:-6px;font-size:10px;padding:1px 6px">' + Store.counts.notifications(me.id) + '</span>' : '') + '</button><a href="#/leads/new" class="btn primary">' + I.plus + 'New lead</a>') +
      '<div class="page"><div class="tiles">' + tile('My open leads', myLeads.length, myLeads.filter((l) => l.createdAt.slice(0, 10) >= Store.addDays(t, -1)).length + ' new since yesterday', '', '#/leads?tab=mine') + tile('Follow-ups due today', my.filter(Store.isToday).length, my.filter(Store.isOverdue).length + ' overdue', 'bad', '#/tasks') + tile('Meetings today', todayEv.length, todayEv.find((e) => e.start > '14:00') ? 'next at ' + todayEv.find((e) => e.start > '14:00').start + ' · ' + esc(todayEv.find((e) => e.start > '14:00').title) : '—', '', '#/calendar') + tile('Quotes awaiting response', myQuotes.length, myQuotes.map((x) => Store.fmtMoney(Store.quoteTotals(x).total, x.currency)).join(' · ') || '—', '', '#/quotes') + '</div>' +
      '<div class="cols"><section class="card" style="flex:1 1 380px;min-width:0"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap"><h2>Tasks &amp; follow-ups</h2><div style="display:flex;gap:6px">' + badge(my.filter(Store.isOverdue).length + ' overdue', 'b-bad') + badge(my.filter(Store.isToday).length + ' today', 'b-purple') + badge(my.filter((x) => !Store.isOverdue(x) && !Store.isToday(x)).length + ' upcoming', 'b-grey') + '</div></div><div style="display:flex;flex-direction:column;gap:8px">' + (my.slice(0, 6).map(taskRow).join('') || '<div class="empty">Nothing due. Nice.</div>') + '</div><a href="#/tasks" style="font-size:13px;font-weight:600">View all ' + my.length + ' tasks</a></section>' +
      '<div style="flex:1 1 340px;min-width:0;display:flex;flex-direction:column;gap:16px"><section class="card"><div style="display:flex;align-items:center;justify-content:space-between"><h2>Today\'s agenda</h2><a href="#/calendar" style="font-size:12.5px;font-weight:600">Open calendar</a></div><div style="display:flex;flex-direction:column;gap:8px;font-size:13px">' + (todayEv.map((e) => '<div style="display:flex;gap:12px;align-items:flex-start"><span style="width:48px;flex:0 0 auto;color:var(--muted);font-weight:600">' + e.start + '</span><span style="border-left:3px solid ' + (e.type === 'call' ? '#BA5326' : e.type === 'internal' ? '#6A5E86' : '#822CDB') + ';padding-left:10px"><strong>' + esc(e.title) + '</strong><span style="display:block;color:var(--muted);font-size:12px">' + esc(e.attendees) + (e.where ? ' · ' + esc(e.where) : '') + (e.leadId ? ' · <a href="#/leads/' + e.leadId + '">' + e.leadId + '</a>' : '') + (e.done ? ' · done' : '') + '</span></span></div>').join('') || '<div style="color:var(--muted)">No events today.</div>') + '</div></section>' +
      '<section class="card"><h2>Notifications</h2><div style="display:flex;flex-direction:column;gap:10px;font-size:13px">' + (notes.map((n) => '<a href="' + n.link + '" style="display:flex;gap:10px;color:var(--text)"><span style="width:8px;height:8px;border-radius:50%;background:' + (n.read ? 'var(--field)' : 'var(--peach)') + ';flex:0 0 auto;margin-top:6px"></span><span><strong>' + esc(n.text) + '</strong><span style="display:block;color:var(--muted);font-size:12px">' + rel(n.at) + (n.detail ? ' · ' + esc(n.detail) : '') + '</span></span></a>').join('') || '<div style="color:var(--muted)">No notifications.</div>') + '</div></section></div>' +
      '<section class="card" style="flex:1 1 280px;min-width:0;max-width:360px"><h2>My pipeline by status</h2><div style="display:flex;flex-direction:column;gap:9px;font-size:12.5px">' + byStatus.map(([s, n], i) => '<div><div style="display:flex;justify-content:space-between"><span>' + esc(s) + '</span><strong>' + n + '</strong></div><div class="bar"><div style="width:' + Math.round(n / max * 100) + '%;background:' + (i > 3 ? '#BA5326' : '#822CDB') + '"></div></div></div>').join('') + '</div><div style="font-size:12px;color:var(--muted)">Won: ' + db().leads.filter((l) => l.assignedTo === me.id && l.status === 'Won').length + ' · Lost: ' + db().leads.filter((l) => l.assignedTo === me.id && l.status === 'Lost').length + '</div></section></div></div>';
    return { html, mount(el) { bindTasks(el); el.querySelector('[data-act=notes]').addEventListener('click', () => { location.hash = '#/notifications'; }); } };
  };

  /* ---------- Tasks ---------- */
  V.tasks = function (q) {
    const me = Store.currentUser(); const scope = q.scope || 'mine';
    let list = db().tasks.filter((x) => scope === 'all' || x.assignedTo === me.id);
    const open = list.filter((x) => !x.done).sort((a, b) => (a.due > b.due ? 1 : -1)); const done = list.filter((x) => x.done);
    const html = topbar('Tasks', 'Pending and overdue follow-ups, new assignments and transferred leads', '<a class="btn' + (scope === 'mine' ? ' primary' : '') + '" href="#/tasks">My tasks</a><a class="btn' + (scope === 'all' ? ' primary' : '') + '" href="#/tasks?scope=all">Team</a>') +
      '<div class="page cols"><section class="card col-main"><h2>Overdue ' + badge(open.filter(Store.isOverdue).length, 'b-bad') + '</h2><div style="display:flex;flex-direction:column;gap:8px">' + (open.filter(Store.isOverdue).map(taskRow).join('') || '<div style="color:var(--muted);font-size:13px">None.</div>') + '</div><h2>Due today ' + badge(open.filter(Store.isToday).length, 'b-purple') + '</h2><div style="display:flex;flex-direction:column;gap:8px">' + (open.filter(Store.isToday).map(taskRow).join('') || '<div style="color:var(--muted);font-size:13px">None.</div>') + '</div><h2>Upcoming</h2><div style="display:flex;flex-direction:column;gap:8px">' + (open.filter((x) => !Store.isOverdue(x) && !Store.isToday(x)).map(taskRow).join('') || '<div style="color:var(--muted);font-size:13px">None.</div>') + '</div></section><aside class="col-side"><section class="card"><h2>Completed</h2><div style="display:flex;flex-direction:column;gap:8px">' + (done.map(taskRow).join('') || '<div style="color:var(--muted);font-size:13px">None yet.</div>') + '</div></section><section class="card"><h2>How tasks get here</h2><ul style="margin:0;padding-left:18px;font-size:13px;color:var(--body);display:flex;flex-direction:column;gap:6px"><li>Lead assigned or transferred to you</li><li>Follow-up date set on a lead</li><li>Added manually on a lead, email or meeting</li><li>Quotation revision requested</li></ul></section></aside></div>';
    return { html, mount: bindTasks };
  };

  /* ---------- Email ---------- */
  V.email = function (id, q) {
    q = q || {}; const me = Store.currentUser(); const folder = q.folder || 'inbox';
    if (id === 'compose') { setTimeout(() => V.compose({ contactId: q.to }), 0); id = null; }
    let list = db().emails.filter((e) => (folder === 'unlinked' ? !e.leadId : folder === 'awaiting' ? e.folder === 'sent' : folder === 'mine' ? e.leadId && (Store.lead(e.leadId) || {}).assignedTo === me.id : e.folder === folder)).sort((a, b) => (a.at < b.at ? 1 : -1));
    const fq = { folder, company: q.company || '', lead: q.lead || '', project: q.project || '' };
    if (fq.project) list = list.filter((e) => e.projectId === fq.project);
    if (fq.company) list = list.filter((e) => e.companyId === fq.company || (e.leadId && (Store.lead(e.leadId) || {}).companyId === fq.company));
    if (fq.lead) list = list.filter((e) => e.leadId === fq.lead);
    if (q.s) { const s = q.s.toLowerCase(); fq.s = q.s; list = list.filter((e) => [e.subject, e.from, e.fromEmail, e.to, e.body].join(' ').toLowerCase().includes(s)); }
    const sel = (id && db().emails.find((e) => e.id === id)) || list[0] || null;
    if (sel && sel.unread) setTimeout(() => Store.markRead(sel.id), 400);
    const clientOpts = db().companies.slice().sort((a, b) => a.name.localeCompare(b.name)).map((c) => ({ value: c.id, label: (c.legalName || c.name) + (c.isClient ? ' · client' : '') }));
    const leadOpts = db().leads.filter((l) => !l.archived && (!fq.company || l.companyId === fq.company)).map((l) => ({ value: l.id, label: l.id + ' · ' + l.companyName + (l.contactId ? ' · ' + Store.contactName(l.contactId) : '') }));
    const projOpts = db().projects.filter((p) => !fq.company || p.companyId === fq.company).map((p) => ({ value: p.id, label: p.id + ' · ' + p.name }));
    const F = (k, label, n, hot) => '<a class="fold' + (folder === k ? ' on' : '') + '" href="#/email?' + qs(Object.assign({}, fq, { folder: k })) + '">' + label + (n ? '<span class="cnt' + (hot ? '' : '') + '"' + (hot ? ' style="background:var(--peach);color:var(--ink)"' : '') + '>' + n + '</span>' : '') + '</a>';
    const sl = sel && sel.leadId ? Store.lead(sel.leadId) : null;
    const acct = Store.accountFor(me.id);
    const html = topbar('Email', acct ? esc(acct.address) + ' · ' + (acct.provider === 'microsoft' ? 'Microsoft 365' : acct.provider === 'google' ? 'Google Workspace' : 'IMAP/SMTP') + ' ' + badge('Connected', 'b-ok') + ' · synced ' + rel(acct.lastSync) + ' · every thread links to a Lead, Contact and Company' : esc(me.email) + ' · ' + badge('Mailbox not connected', 'b-warn'), (acct ? '<button class="btn" data-act="sync">Sync now</button>' : '<a class="btn" href="#/settings">Connect Microsoft 365</a>') + '<button class="btn primary" data-act="compose">+ Compose</button>') +
      (acct ? '' : '<div style="margin:16px 28px 0;padding:12px 16px;border:1px solid #F0C98A;background:#FFF8EC;border-radius:10px;font-size:13px;color:var(--body);display:flex;gap:12px;align-items:center;flex-wrap:wrap"><span><strong>Connect your mailbox to send and receive from the CRM.</strong> Your Microsoft 365 Business Basic account works out of the box; sign in once and the CRM syncs mail and calendar through Microsoft Graph.</span><div class="grow"></div><button class="btn primary" data-act="connectms">Connect Microsoft 365</button></div>') +
      '<div class="filters" style="background:var(--surface);padding:10px 28px;border-bottom:1px solid var(--line)"><span style="font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em;margin-right:4px">Show mail for</span><select class="chip" name="fCompany" aria-label="Client / company" style="width:260px" data-search>' + opts(clientOpts, fq.company, 'Client: all') + '</select><select class="chip" name="fLead" aria-label="Lead" style="width:260px" data-search>' + opts(leadOpts, fq.lead, fq.company ? 'Lead: all for this client' : 'Lead: all') + '</select>' + '<select class="chip" name="fProject" aria-label="Project" style="width:240px" data-search>' + opts(projOpts, fq.project, fq.company ? 'Project: all for this client' : 'Project: all') + '</select>' + (fq.company || fq.lead || fq.project ? '<a class="btn sm" href="#/email?folder=' + folder + '">✕ Clear</a>' : '') + '<div class="grow"></div><label class="search" style="height:34px;width:300px">' + I.search + '<span class="sr">Search mail</span><input type="search" name="fs" value="' + esc(q.s || '') + '" placeholder="Search subject, sender, text…"></label></div>' +
      '<div class="mail"><nav class="folders" aria-label="Mail folders">' + F('inbox', 'Inbox', db().emails.filter((e) => e.folder === 'inbox' && e.unread).length) + F('sent', 'Sent') + F('drafts', 'Drafts') + F('archive', 'Archive') + '<div class="navsec" style="color:var(--muted)">Smart views</div>' + F('unlinked', 'Unlinked', db().emails.filter((e) => !e.leadId).length, true) + F('awaiting', 'Awaiting reply') + F('mine', 'My leads') + '<div class="navsec" style="color:var(--muted)">Templates</div>' + Store.templatesFor(me.lang || 'en').slice(0, 6).map((x) => '<button class="fold" data-tpl="' + x.id + '" title="' + esc(x.subject) + '">' + esc(x.name) + (x.source === 'oft' ? ' <span style="font-size:10px;color:var(--muted)">.oft</span>' : '') + '</button>').join('') + '<a class="fold" href="#/settings" style="color:var(--purple)">Manage templates…</a></nav>' +
      '<section class="msglist" aria-label="Message list"><div style="display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--muted)"><strong style="color:var(--text);text-transform:capitalize">' + esc(folder) + '</strong> · ' + list.length + (fq.company ? ' · ' + esc((Store.company(fq.company) || {}).name || '') : '') + (fq.lead ? ' · ' + esc(fq.lead) : '') + '</div>' + (list.map((e) => '<a class="msg' + (sel && sel.id === e.id ? ' on' : '') + (e.unread ? ' unread' : '') + '" href="#/email/' + e.id + '?folder=' + folder + '"><span class="av">' + esc(UI.initials(e.from)) + '</span><span style="min-width:0;flex-grow:1"><span class="who">' + esc(e.folder === 'sent' ? 'To: ' + e.to : e.from) + ' <span class="t">' + rel(e.at).replace(/, /, ' ') + '</span></span><span class="sub">' + esc(e.subject) + '</span><span class="pre">' + esc(e.body.replace(/\s+/g, ' ').slice(0, 80)) + '</span><span style="display:block;margin-top:4px">' + (e.leadId ? badge(e.leadId, 'b-purple') : badge('Unlinked · create lead?', 'b-warn')) + (e.quoteId ? ' ' + badge(e.quoteId, 'b-warn') : '') + (e.projectId ? ' ' + badge(e.projectId, 'b-ok') : '') + '</span></span></a>').join('') || '<div class="empty">' + (fq.company || fq.lead ? 'No messages for this filter in ' + esc(folder) + '.' : 'Nothing here.') + '</div>') + '</section>' +
      (sel ? '<article class="reader"><div style="padding:18px 24px 14px;border-bottom:1px solid var(--line);display:flex;flex-wrap:wrap;gap:12px;align-items:flex-start"><div style="min-width:0;flex-grow:1"><h2 style="font-size:16px">' + esc(sel.subject) + '</h2><div style="font-size:12.5px;color:var(--muted);margin-top:4px">' + esc(sel.from) + ' &lt;' + esc(sel.fromEmail) + '&gt; to ' + esc(sel.to) + ' · ' + fmtDT(sel.at) + '</div></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn sm" data-act="reply">Reply</button><button class="btn sm" data-act="logact"' + (sel.leadId ? '' : ' disabled') + '>Log as activity</button>' + (sel.leadId ? '' : '<button class="btn sm primary" data-act="link">Link to lead / create lead</button>') + '</div></div><div class="body">' + esc(sel.body) + '</div><div style="margin-top:auto;padding:14px 24px;border-top:1px solid var(--line);display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12.5px;color:var(--muted)">Suggested actions: ' + (sel.leadId ? '<a class="btn sm" href="#/calendar?new=1&lead=' + sel.leadId + '">Create meeting</a><a class="btn sm" href="#/companies/' + sel.companyId + '/contacts">Add contact</a><button class="btn sm" data-act="task">Add follow-up task</button>' : '<button class="btn sm" data-act="link">Create lead from this email</button>') + '</div></article>' +
      '<aside class="mailside"><div class="navsec" style="padding:0 0 4px;color:var(--muted)">Linked records</div>' + (sl ? '<a class="link" href="#/leads/' + sl.id + '"><span><strong>Lead</strong><span style="display:block;color:var(--muted)">' + sl.id + ' · ' + esc(sl.status) + '</span></span>' + prio(sl.priority) + '</a><a class="link" href="#/companies/' + sl.companyId + '/contacts"><span><strong>Contact</strong><span style="display:block;color:var(--muted)">' + esc(Store.contactName(sel.contactId) || '—') + '</span></span></a><a class="link" href="#/companies/' + sl.companyId + '"><span><strong>Company</strong><span style="display:block;color:var(--muted)">' + esc((Store.company(sl.companyId) || {}).name || '') + '</span></span></a>' : '<div class="note warn">No matching contact or lead. Link it to an existing lead or create one.</div>') + '<div class="navsec" style="padding:8px 0 4px;color:var(--muted)">Thread history</div><div style="font-size:12.5px;color:var(--body);display:flex;flex-direction:column;gap:6px">' + (sel.history || []).map((h) => '<div>' + esc(h) + '</div>').join('') + '</div>' + (sl && sl.followUp ? '<div class="navsec" style="padding:8px 0 4px;color:var(--muted)">Follow-up</div><div style="font-size:12.5px;color:var(--body)">Next follow-up on this lead: <strong>' + fmtDate(sl.followUp) + '</strong></div>' : '') + '</aside>' : '<div class="reader empty">Select a message.</div>') + '</div>';
    return { html, mount(el) {
      const act = (n, fn) => el.querySelectorAll('[data-act=' + n + ']').forEach((b) => b.addEventListener('click', fn));
      const fc = el.querySelector('[name=fCompany]'); const fl = el.querySelector('[name=fLead]');
      fc.addEventListener('change', () => { location.hash = '#/email?' + qs({ folder, company: fc.value, lead: '', s: q.s }); });
      fl.addEventListener('change', () => { const l = fl.value ? Store.lead(fl.value) : null; location.hash = '#/email?' + qs({ folder, company: l ? l.companyId : fq.company, lead: fl.value, s: q.s }); });
      const fp = el.querySelector('[name=fProject]'); fp.addEventListener('change', () => { const pr = fp.value ? db().projects.find((x) => x.id === fp.value) : null; location.hash = '#/email?' + qs({ folder, company: pr ? pr.companyId : fq.company, lead: fq.lead, project: fp.value, s: q.s }); });
      if (q.compose) setTimeout(() => V.compose({ companyId: fq.company, leadId: fq.lead, projectId: fq.project }), 0);
      const fs = el.querySelector('[name=fs]'); fs.addEventListener('change', () => { location.hash = '#/email?' + qs(Object.assign({}, fq, { s: fs.value })); });
      act('compose', () => V.compose({ companyId: fq.company, leadId: fq.lead, projectId: fq.project }));
      act('connectms', () => V.connectModal('microsoft'));
      act('sync', () => { Store.syncMailbox(acct.id); toast('Synced with ' + (acct.provider === 'microsoft' ? 'Microsoft 365' : 'mailbox') + ' · 1 new message linked'); });
      act('reply', () => V.compose({ to: sel.fromEmail, subject: (sel.subject.startsWith('Re:') ? '' : 'Re: ') + sel.subject, leadId: sel.leadId, contactId: sel.contactId, companyId: sel.companyId }));
      act('logact', () => { Store.logActivity(sel.leadId, 'email', 'Email from ' + sel.from + ': ' + sel.subject); toast('Logged on ' + sel.leadId); });
      act('task', () => { Store.createTask(sel.leadId, 'Reply to ' + sel.from + ' · ' + sel.subject, Store.addDays(Store.today(), 1), me.id); toast('Task created'); });
      act('link', () => modal('<h2>Link email to a lead</h2><div><label class="lbl">Existing lead</label><select class="in" name="leadId"><option value="">— create a new lead from this email —</option>' + opts(db().leads.filter((l) => !l.archived).map((l) => ({ value: l.id, label: l.id + ' · ' + l.companyName }))) + '</select></div><div class="note info">Creating a lead runs the same duplicate check as the lead form: the sender\'s email domain is matched against existing companies first.</div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Link</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { const lid = bg.querySelector('[name=leadId]').value; if (lid) { Store.linkEmail(sel.id, lid); close(); toast('Linked to ' + lid); return; } const dom = Store.domainOf(sel.fromEmail); const cm = Store.matchCompany({ email: sel.fromEmail }); const nameGuess = sel.from.includes('@') ? dom.split('.')[0].replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase()) : sel.from; const l = Store.createLead({ companyName: cm.match ? cm.match.name : nameGuess, email: sel.fromEmail, country: cm.match ? cm.match.country : 'United States', source: 'Other', sourceUrl: null, notes: sel.subject + '\n\n' + sel.body, followUp: Store.addDays(Store.today(), 2) }, { linkCompanyId: cm.match ? cm.match.id : null }); Store.linkEmail(sel.id, l.id); close(); toast('Lead ' + l.id + ' created and linked'); location.hash = '#/leads/' + l.id; })));
      el.querySelectorAll('[data-tpl]').forEach((b) => b.addEventListener('click', () => { const T = (db().templates || []).find((x) => x.id === b.dataset.tpl); if (T) V.compose({ subject: Store.fillTemplate(T.subject, { me: me.name }), body: Store.fillTemplate(T.body, { me: me.name }) }); }));
    } };
  };
  /* V.compose lives in views-projects.js (Client → Lead → Project composer). */

  /* Calendar and Notifications are in views-calendar.js */

  /* ---------- Quotations ---------- */
  V.quotes = function (q) {
    q = q || {}; const tab = q.tab || 'all'; const t = Store.today();
    let rows = db().quotes.slice().sort((a, b) => (a.date < b.date ? 1 : -1));
    const groups = { all: () => true, draft: (x) => x.status === 'Draft', sent: (x) => ['Sent', 'Negotiating'].includes(x.status), accepted: (x) => x.status === 'Accepted', closed: (x) => ['Rejected', 'Expired'].includes(x.status) };
    rows = rows.filter(groups[tab]); if (q.s) { const s = q.s.toLowerCase(); rows = rows.filter((x) => [x.id, (Store.company(x.companyId) || {}).name, x.leadId, x.subject].join(' ').toLowerCase().includes(s)); }
    const all = db().quotes; const open = all.filter(groups.sent); const T = (k, label, n) => '<a class="tab' + (tab === k ? ' on' : '') + '" href="#/quotes?' + qs({ tab: k === 'all' ? '' : k, s: q.s }) + '">' + label + ' <span class="n">' + n + '</span></a>';
    const sum = (list) => { const o = {}; list.forEach((x) => { o[x.currency] = (o[x.currency] || 0) + Store.quoteTotals(x).total; }); return Object.keys(o).map((k) => Store.fmtMoney(o[k], k).replace(/\.00$/, '')).join(' · ') || '—'; };
    const html = topbar('Quotations', 'Every quotation links to a lead, company and contact. Revisions keep previous versions.', '<label class="search">' + I.search + '<span class="sr">Search quotations</span><input type="search" name="s" value="' + esc(q.s || '') + '" placeholder="Search number, company, lead…"></label><a href="#/quotes/new" class="btn primary">' + I.plus + 'New quotation</a>') +
      '<div class="page"><div class="tiles">' + tile('Open value (sent + negotiating)', open.length, sum(open)) + tile('Accepted', all.filter(groups.accepted).length, sum(all.filter(groups.accepted)), 'ok') + tile('Expiring within 7 days', open.filter((x) => x.validUntil && x.validUntil <= Store.addDays(t, 7)).length, open.filter((x) => x.validUntil && x.validUntil <= Store.addDays(t, 7)).map((x) => x.id + ' · ' + fmtDate(x.validUntil)).join(', ') || '—', 'bad') + tile('Win rate', Math.round(all.filter(groups.accepted).length / Math.max(1, all.filter((x) => x.status !== 'Draft').length) * 100) + '%', all.filter(groups.accepted).length + ' of ' + all.filter((x) => x.status !== 'Draft').length + ' sent') + '</div>' +
      '<div class="card flush"><div class="tabs">' + T('all', 'All', all.length) + T('draft', 'Draft', all.filter(groups.draft).length) + T('sent', 'Sent / Negotiating', open.length) + T('accepted', 'Accepted', all.filter(groups.accepted).length) + T('closed', 'Rejected / Expired', all.filter(groups.closed).length) + '</div><div class="tbl"><table><thead><tr><th>Quotation no.</th><th>Company</th><th>Contact</th><th>Lead</th><th>Date</th><th>Valid until</th><th>Total</th><th>Rev.</th><th>Status</th><th>Owner</th><th></th></tr></thead><tbody>' + (rows.map((x) => { const c = Store.company(x.companyId); const exp = x.validUntil && x.validUntil <= Store.addDays(t, 7) && groups.sent(x); return '<tr><td><a href="#/quotes/' + x.id + '" style="font-weight:600">' + x.id + '</a></td><td><a href="#/companies/' + x.companyId + '" style="color:var(--text);font-weight:600">' + esc(c ? c.legalName || c.name : '—') + '</a></td><td>' + esc(Store.contactName(x.contactId) || '—') + '</td><td>' + (x.leadId ? '<a href="#/leads/' + x.leadId + '">' + x.leadId + '</a>' : '—') + '</td><td>' + fmtDate(x.date) + '</td><td>' + (exp ? '<span style="color:var(--bad-fg);font-weight:600">' + fmtDate(x.validUntil) + '</span>' : x.validUntil ? fmtDate(x.validUntil) : '<span class="dim">—</span>') + '</td><td style="font-weight:600">' + Store.fmtMoney(Store.quoteTotals(x).total, x.currency) + '</td><td>rev ' + x.revision + '</td><td>' + badge(x.status) + '</td><td>' + userLabel(x.ownerId) + '</td><td>' + (x.status === 'Accepted' && !x.projectId ? '<a href="#/quotes/' + x.id + '" style="color:var(--orange);font-weight:600;font-size:12.5px">Convert to project</a>' : '<a href="#/quotes/' + x.id + '" style="font-size:12.5px;font-weight:600">Open</a>') + '</td></tr>'; }).join('') || '<tr><td colspan="11" class="empty">No quotations.</td></tr>') + '</tbody></table></div></div></div>';
    return { html, mount(el) { const s = el.querySelector('input[name=s]'); s.addEventListener('change', () => { location.hash = '#/quotes?' + qs({ tab: q.tab, s: s.value }); }); } };
  };

  V.quoteEditor = function (id, q) {
    q = q || {};
    if (id === 'new') { const l = q.lead ? Store.lead(q.lead) : null; const cid = l ? l.companyId : q.company || db().companies[0].id; const c = Store.company(cid); const ct = l && l.contactId ? Store.contact(l.contactId) : db().contacts.find((x) => x.companyId === cid && x.primary) || db().contacts.find((x) => x.companyId === cid); let nq; App.silent(() => { nq = Store.createQuote({ companyId: cid, contactId: ct ? ct.id : null, leadId: l ? l.id : (db().leads.find((x) => x.companyId === cid) || {}).id || null, subject: 'Advisory services for ' + (c ? c.name : 'client') }); }); setTimeout(() => { location.hash = '#/quotes/' + nq.id; }, 0); return { html: topbar('Creating quotation…') }; }
    const x = db().quotes.find((k) => k.id === id); if (!x) return { html: topbar('Quotation not found') + '<div class="page"><div class="empty"><a href="#/quotes">Back to quotations</a></div></div>' };
    const c = Store.company(x.companyId); const tot = Store.quoteTotals(x); const locked = ['Accepted', 'Rejected', 'Expired'].includes(x.status);
    const money = (n) => Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const steps = ['Draft', 'Sent', 'Negotiating', 'Accepted']; const idx = { Draft: 0, Sent: 1, Negotiating: 2, Accepted: 3, Rejected: -1, Expired: -1 }[x.status];
    const html = topbar(x.id + ' · ' + esc(c ? c.legalName || c.name : '') + ' ' + badge(x.status) + ' ' + badge('Revision ' + x.revision + (x.editingNewRevision ? ' · editing' : ''), 'b-grey'), 'Lead ' + (x.leadId ? '<a href="#/leads/' + x.leadId + '">' + x.leadId + '</a>' : '—') + ' · Contact ' + esc(Store.contactName(x.contactId) || '—') + ' · Company <a href="#/companies/' + x.companyId + '">' + x.companyId + '</a> · Owner ' + esc(Store.userName(x.ownerId)), '<button class="btn" data-act="pdf">Preview PDF</button><button class="btn" data-act="dup">Duplicate</button>' + (locked ? '' : '<button class="btn primary" data-act="send">Send by email</button>'), '<a href="#/quotes">Quotations</a> / ' + x.id) +
      '<div class="page cols"><div class="col-main"><section class="card"><h2>Quotation details</h2><div class="grid4"><div><label class="lbl">Quotation number</label><input class="in" value="' + x.id + '" readonly style="background:#F9F7FD"></div><div><label class="lbl">Quotation date</label><input class="in" type="date" name="date" value="' + x.date + '"' + (locked ? ' disabled' : '') + '></div><div><label class="lbl">Valid until</label><input class="in" type="date" name="validUntil" value="' + (x.validUntil || '') + '"' + (locked ? ' disabled' : '') + '></div><div><label class="lbl">Currency</label><select class="in" name="currency"' + (locked ? ' disabled' : '') + '>' + opts(db().config.currencies, x.currency) + '</select></div><div class="span2"><label class="lbl">Company</label><input class="in" value="' + esc(c ? c.legalName || c.name : '') + ' · ' + x.companyId + '" readonly style="background:#F9F7FD"></div><div><label class="lbl">Contact</label><select class="in" name="contactId"' + (locked ? ' disabled' : '') + '>' + opts(db().contacts.filter((k) => k.companyId === x.companyId).map((k) => ({ value: k.id, label: k.firstName + ' ' + k.lastName + ' · ' + (k.designation || k.type) })), x.contactId, '— none —') + '</select></div><div><label class="lbl">Lead</label><select class="in" name="leadId"' + (locked ? ' disabled' : '') + '>' + opts(db().leads.filter((k) => k.companyId === x.companyId).map((k) => ({ value: k.id, label: k.id + ' · ' + k.status })), x.leadId, '— none —') + '</select></div><div class="span4"><label class="lbl">Subject</label><input class="in" name="subject" value="' + esc(x.subject || '') + '"' + (locked ? ' disabled' : '') + '></div></div></section>' +
      '<section class="card flush"><div class="head"><h2>Products &amp; services</h2><span style="font-size:12.5px;color:var(--muted)">Prices can be overridden per quotation. Totals update as you type.</span><div class="grow"></div>' + (locked ? '' : '<button class="btn sm" data-act="addline">+ Add line</button>') + '</div><div class="tbl"><table><thead><tr><th style="width:34%">Item</th><th>Qty</th><th>Unit</th><th class="num">Unit price</th><th class="num">Discount %</th><th class="num">Line total</th><th></th></tr></thead><tbody>' + x.lines.map((l) => '<tr data-line="' + l.id + '"><td class="wrap"><input class="cell" style="width:100%;font-weight:600" name="item" value="' + esc(l.item) + '"' + (locked ? ' disabled' : '') + '><input class="cell" style="width:100%;margin-top:4px;font-size:12px;color:var(--muted)" name="desc" placeholder="Description" value="' + esc(l.desc || '') + '"' + (locked ? ' disabled' : '') + '></td><td><input class="cell num" style="width:64px" name="qty" type="number" min="0" step="1" value="' + l.qty + '"' + (locked ? ' disabled' : '') + '></td><td><input class="cell" style="width:90px" name="unit" value="' + esc(l.unit) + '"' + (locked ? ' disabled' : '') + '></td><td class="num"><input class="cell num" style="width:120px" name="price" type="number" min="0" step="0.01" value="' + l.price + '"' + (locked ? ' disabled' : '') + '></td><td class="num"><input class="cell num" style="width:70px" name="discount" type="number" min="0" max="100" value="' + (l.discount || 0) + '"' + (locked ? ' disabled' : '') + '></td><td class="num" style="font-weight:600" data-ltotal>' + money(l.qty * l.price * (1 - (l.discount || 0) / 100)) + '</td><td>' + (locked ? '' : '<button class="btn xs" data-del="' + l.id + '" aria-label="Remove line">×</button>') + '</td></tr>').join('') + '</tbody></table></div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:20px;padding:16px 20px;border-top:1px solid var(--line)"><div style="flex:1 1 320px;min-width:0"><label class="lbl">Notes &amp; terms shown on the PDF</label><textarea class="in" name="notes" rows="5"' + (locked ? ' disabled' : '') + '>' + esc(x.notes || '') + '</textarea></div><div class="totals" style="flex:0 1 300px"><span style="color:var(--muted)">Subtotal</span><span class="num" data-t="sub">' + money(tot.sub) + '</span><span style="color:var(--muted)">Line discounts</span><span class="num" data-t="disc">− ' + money(tot.disc) + '</span><span style="color:var(--muted)">Overall discount <input class="cell num" style="width:60px;height:28px;margin-left:6px" name="overallDiscount" type="number" min="0" max="100" value="' + (x.overallDiscount || 0) + '"' + (locked ? ' disabled' : '') + '> %</span><span class="num" data-t="overall">− ' + money(tot.overall) + '</span><span style="color:var(--muted)">Net</span><span class="num" data-t="net">' + money(tot.net) + '</span><span style="color:var(--muted)">Tax <input class="cell num" style="width:60px;height:28px;margin-left:6px" name="taxRate" type="number" min="0" max="100" value="' + x.taxRate + '"' + (locked ? ' disabled' : '') + '> %</span><span class="num" data-t="tax">' + money(tot.tax) + '</span><span class="big">Total <span data-t="cur">' + x.currency + '</span></span><span class="num big" data-t="total">' + money(tot.total) + '</span></div></div></section></div>' +
      '<aside class="col-side"><section class="card"><h2>Status</h2><div style="display:flex;flex-direction:column;gap:10px">' + steps.map((s, i) => '<div class="step"><span class="d' + (idx >= i ? ' on' : '') + '"></span><span' + (idx >= i ? '' : ' style="color:var(--muted)"') + '><strong>' + s + '</strong>' + (x.history.filter((h) => h.text.startsWith(s)).slice(-1).map((h) => ' · ' + rel(h.at) + ' · ' + esc(h.text.replace(s + ' · ', ''))).join('') || '') + '</span></div>').join('') + '<div class="step"><span class="d' + (idx === -1 ? ' on' : '') + '" style="' + (idx === -1 ? 'background:var(--bad-fg)' : '') + '"></span><span style="color:var(--muted)">Rejected / Expired' + (idx === -1 ? ' · ' + esc(x.status) : '') + '</span></div></div><div style="display:flex;gap:8px;flex-wrap:wrap">' + (locked ? (x.status === 'Accepted' && !x.projectId ? '<button class="btn sm primary" data-act="convert">Convert to project</button>' : x.projectId ? badge('Project ' + x.projectId, 'b-ok') : '') : '<button class="btn sm" data-act="accept">Mark accepted</button><button class="btn sm" data-act="reject">Mark rejected</button>' + (x.status === 'Sent' ? '<button class="btn sm" data-act="negotiate">Negotiating</button>' : '')) + '</div></section>' +
      '<section class="card"><h2>Revisions</h2><div style="font-size:13px;display:flex;flex-direction:column;gap:10px"><div style="padding:10px 12px;border:1px solid #822CDB;background:var(--tint);border-radius:8px"><strong>Rev ' + x.revision + (x.editingNewRevision || x.status === 'Draft' ? ' · editing' : ' · current') + '</strong><div style="color:var(--body);font-size:12.5px;margin-top:2px">' + x.lines.length + ' lines · ' + Store.fmtMoney(tot.total, x.currency) + '</div></div>' + x.revisions.slice().reverse().filter((r) => !(r.rev === x.revision && !x.editingNewRevision)).map((r) => '<div style="padding:10px 12px;border:1px solid var(--line);border-radius:8px"><strong>Rev ' + r.rev + ' · sent ' + fmtDate(r.at) + '</strong><div style="color:var(--body);font-size:12.5px;margin-top:2px">' + Store.fmtMoney(r.total, x.currency) + ' · ' + esc(r.note || '') + '</div></div>').join('') + '</div><div style="font-size:12px;color:var(--muted)">Every send creates a frozen revision. Edits after sending always open a new revision.</div></section>' +
      '<section class="card"><h2>History</h2><div style="font-size:12.5px;color:var(--body);display:flex;flex-direction:column;gap:6px">' + x.history.slice().reverse().map((h) => '<div>' + rel(h.at) + ' · ' + esc(h.text) + '</div>').join('') + '</div></section><section class="card"><h2>On accept</h2><div style="font-size:13px;color:var(--body);line-height:1.5">Lead moves to <strong>Won</strong>, the company gets a <strong>Client</strong> flag, and "Convert to project" creates a project with these line items as the scope. No new company or contact record is created.</div></section></aside></div>';
    return { html, mount(el) {
      if (locked) { } else {
        const recalc = () => { const lines = [...el.querySelectorAll('[data-line]')].map((tr) => ({ id: tr.dataset.line, item: tr.querySelector('[name=item]').value, desc: tr.querySelector('[name=desc]').value, qty: Number(tr.querySelector('[name=qty]').value) || 0, unit: tr.querySelector('[name=unit]').value, price: Number(tr.querySelector('[name=price]').value) || 0, discount: Number(tr.querySelector('[name=discount]').value) || 0 })); const patch = { lines, overallDiscount: Number(el.querySelector('[name=overallDiscount]').value) || 0, taxRate: Number(el.querySelector('[name=taxRate]').value) || 0, notes: el.querySelector('[name=notes]').value, subject: el.querySelector('[name=subject]').value, date: el.querySelector('[name=date]').value, validUntil: el.querySelector('[name=validUntil]').value || null, currency: el.querySelector('[name=currency]').value, contactId: el.querySelector('[name=contactId]').value || null, leadId: el.querySelector('[name=leadId]').value || null }; const wasEditing = x.editingNewRevision; Store.updateQuote(id, patch); if (x.editingNewRevision !== wasEditing) { return true; } const t2 = Store.quoteTotals(x); el.querySelectorAll('[data-line]').forEach((tr, i) => { const l = x.lines[i] || lines[i]; tr.querySelector('[data-ltotal]').textContent = money(l.qty * l.price * (1 - l.discount / 100)); }); const set = (k, v) => { el.querySelector('[data-t=' + k + ']').textContent = v; }; set('sub', money(t2.sub)); set('disc', '− ' + money(t2.disc)); set('overall', '− ' + money(t2.overall)); set('net', money(t2.net)); set('tax', money(t2.tax)); set('total', money(t2.total)); set('cur', x.currency); };
        el.querySelectorAll('input,textarea,select').forEach((i) => i.addEventListener('input', () => { let bumped = false; App.silent(() => { bumped = recalc(); }); if (bumped) { App.render(); toast('Revision ' + x.revision + ' opened · previous version kept'); } }));
        el.querySelector('[data-act=addline]').addEventListener('click', () => { Store.updateQuote(id, { lines: x.lines.concat([{ id: Store.uid('l'), item: 'New line', desc: '', qty: 1, unit: 'unit', price: 0, discount: 0 }]) }); });
        el.querySelectorAll('[data-del]').forEach((b) => b.addEventListener('click', () => { Store.updateQuote(id, { lines: x.lines.filter((l) => l.id !== b.dataset.del) }); }));
        el.querySelector('[data-act=send]').addEventListener('click', () => !(Store.contact(x.contactId) || {}).email ? toast('Choose a contact with an email address before sending', 'warn') : modal('<h2>Send ' + x.id + ' by email</h2><p style="margin:0;font-size:13px;color:var(--body)">A PDF of revision ' + x.revision + ' (' + Store.fmtMoney(Store.quoteTotals(x).total, x.currency) + ') is attached and the revision is frozen. The lead moves to <strong>Proposal Sent</strong> if it is earlier in the pipeline.</p><div><label class="lbl">To</label><input class="in" value="' + esc((Store.contact(x.contactId) || {}).email || '') + '" readonly></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn primary" data-go>Send</button></div>', (bg, close) => bg.querySelector('[data-go]').addEventListener('click', () => { try { close(); Store.sendQuote(id); toast(x.id + ' sent · revision frozen · email logged'); } catch (err) { toast(err.message, 'warn'); } })));
        const st = (n, s) => { const b = el.querySelector('[data-act=' + n + ']'); if (b) b.addEventListener('click', () => { Store.setQuoteStatus(id, s); toast(x.id + ' marked ' + s); }); };
        st('accept', 'Accepted'); st('reject', 'Rejected'); st('negotiate', 'Negotiating');
      }
      const cv = el.querySelector('[data-act=convert]'); if (cv) cv.addEventListener('click', () => { try { const p = Store.convertQuote(id); toast('Project ' + p.id + ' created from ' + id); } catch (err) { toast(err.message, 'warn'); } });
      el.querySelector('[data-act=dup]').addEventListener('click', () => { const nq = Store.createQuote({ companyId: x.companyId, contactId: x.contactId, leadId: x.leadId, subject: x.subject + ' (copy)', lines: JSON.parse(JSON.stringify(x.lines)), currency: x.currency, taxRate: x.taxRate, notes: x.notes }); toast('Duplicated as ' + nq.id); location.hash = '#/quotes/' + nq.id; });
      el.querySelector('[data-act=pdf]').addEventListener('click', () => { const t2 = Store.quoteTotals(x); const ct = Store.contact(x.contactId); modal('<div style="font-family:Montserrat;color:#1F1533"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px"><img src="assets/logo-full.png" alt="DAIT Partners" style="height:48px"><div style="text-align:right;font-size:12px;color:#6A5E86">DAIT Partners<br>crm.daitpartners.com<br>hello@daitpartners.com</div></div><h2 style="font-size:22px;font-weight:800;margin:18px 0 4px;color:#1F0249">Quotation ' + x.id + '</h2><div style="font-size:12.5px;color:#6A5E86">Date ' + fmtDate(x.date) + ' · Valid until ' + (x.validUntil ? fmtDate(x.validUntil) : '—') + ' · Revision ' + x.revision + '</div><div style="display:flex;gap:24px;margin:16px 0;font-size:13px"><div><strong>To</strong><br>' + esc(c ? c.legalName || c.name : '') + '<br>' + esc(ct ? ct.firstName + ' ' + ct.lastName : '') + '<br>' + esc([c && c.city, c && c.country].filter(Boolean).join(', ')) + '</div><div><strong>Subject</strong><br>' + esc(x.subject || '') + '</div></div><table style="font-size:12.5px"><thead><tr><th>Item</th><th class="num">Qty</th><th class="num">Unit price</th><th class="num">Total</th></tr></thead><tbody>' + x.lines.map((l) => '<tr><td class="wrap"><strong>' + esc(l.item) + '</strong>' + (l.desc ? '<br><span style="color:#6A5E86">' + esc(l.desc) + '</span>' : '') + (l.discount ? '<br><span style="color:#6A5E86">' + l.discount + '% discount</span>' : '') + '</td><td class="num">' + l.qty + ' ' + esc(l.unit) + '</td><td class="num">' + money(l.price) + '</td><td class="num">' + money(l.qty * l.price * (1 - (l.discount || 0) / 100)) + '</td></tr>').join('') + '</tbody></table><div class="totals" style="margin-top:12px;margin-left:auto;max-width:280px"><span>Net</span><span class="num">' + money(t2.net) + '</span><span>Tax ' + x.taxRate + '%</span><span class="num">' + money(t2.tax) + '</span><span class="big">Total ' + x.currency + '</span><span class="num big">' + money(t2.total) + '</span></div><p style="font-size:12px;color:#4A3F66;white-space:pre-wrap;margin-top:16px">' + esc(x.notes || '') + '</p></div><div class="actions"><button class="btn" data-close>Close</button><button class="btn primary" onclick="window.print()">Print / Save as PDF</button></div>'); });
    } };
  };
})();
